<?php
require_once __DIR__.'/alfa_acquiring.php';
$orderId=trim((string)($_GET['order']??''));$token=trim((string)($_GET['token']??''));$order=null;
foreach(av_read_orders() as $candidate)if(($candidate['id']??'')===$orderId&&empty($candidate['user_id'])&&av_guest_order_access($candidate,$token)){$order=$candidate;break;}
if(!$order){http_response_code(404);exit('Заказ не найден или ссылка недействительна.');}
$ready=av_alfa_ready(true);$method=$order['payment_method']??'cash';$status=$order['payment_status']??($method==='cash'?'cash_due':'unpaid');$amount=(float)($order['final_price']??$order['estimated_price']??0);
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer"><title>Заказ <?php echo htmlspecialchars($orderId);?> — AV Rescue</title><style>:root{--red:#ed111c;--panel:#111317;--line:#30343a;--muted:#aeb0b4}*{box-sizing:border-box}body{margin:0;background:#08090a;color:#fff;font-family:Arial,Helvetica,sans-serif}.card{width:min(620px,calc(100% - 28px));margin:8vh auto;background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:28px}.brand{font-size:30px;font-weight:900}.brand b{color:var(--red)}.summary{margin:22px 0;padding:18px;border-radius:10px;background:#0a0c0e;border:1px solid var(--line)}.summary p{margin:8px 0}.muted{color:var(--muted);line-height:1.5}.status{display:inline-block;padding:7px 10px;border-radius:999px;background:#24272c;font-weight:800}.btn{display:inline-flex;padding:13px 18px;border-radius:8px;background:var(--red);border:1px solid var(--red);color:#fff;text-decoration:none;font-weight:800;cursor:pointer}.btn.secondary{background:#17191c;border-color:#555;margin-left:8px}.btn:disabled{opacity:.55;cursor:not-allowed}@media(max-width:520px){.card{margin:18px auto;padding:20px}.btn{width:100%;margin:7px 0!important}}</style></head><body><main class="card"><a class="brand" href="/">AV<b>R</b> Rescue</a><h1>Заказ <?php echo htmlspecialchars($orderId);?></h1><div class="summary"><p><b><?php echo htmlspecialchars($order['service']??'Помощь на дороге');?></b></p><p class="muted"><?php echo htmlspecialchars($order['address']??'');?></p><p>Сумма: <b><?php echo number_format($amount,0,'.',' ');?> ₽</b></p><p>Способ: <?php echo htmlspecialchars(av_payment_method_label($method));?></p><p>Статус: <span class="status" id="paymentStatus"><?php echo htmlspecialchars(av_payment_status_label($status));?></span></p></div><?php if(in_array($method,array('card','sbp'),true)&&$status!=='paid'):?><button class="btn" id="payButton" <?php echo $ready?'':'disabled';?>>Перейти к оплате</button><?php if(!$ready):?><p class="muted">Онлайн-оплата будет доступна после подключения банка. Заявка уже создана и передана диспетчеру.</p><?php endif;?><?php endif;?><button class="btn secondary" id="refreshButton">Обновить статус</button><p class="muted">Сохраните эту ссылку: по ней можно вернуться к оплате и проверить её статус без регистрации.</p></main><script>const ORDER=<?php echo json_encode($orderId);?>,TOKEN=<?php echo json_encode($token);?>;const pay=document.getElementById('payButton');if(pay)pay.addEventListener('click',async()=>{pay.disabled=true;try{const r=await fetch('/api/alfa_create_payment.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_id:ORDER,guest_token:TOKEN})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Не удалось начать оплату');if(d.status==='paid'){location.reload();return}if(!d.payment_url)throw new Error('Банк не вернул ссылку на оплату');location.href=d.payment_url}catch(e){alert(e.message);pay.disabled=false}});document.getElementById('refreshButton').addEventListener('click',async()=>{try{const r=await fetch('/api/alfa_payment_status.php?order_id='+encodeURIComponent(ORDER)+'&guest_token='+encodeURIComponent(TOKEN),{cache:'no-store'});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Не удалось проверить оплату');location.reload()}catch(e){alert(e.message)}});</script></body></html>
